# interface-interaction

## Overview
Functional capability to execute UI interactions programmatically - clicking, typing, navigating, form filling, and handling interface elements.

## When to Use
- Automating UI workflows
- Filling forms and inputs
- Navigating menus and tabs
- Handling modals and dialogs
- Drag and drop operations
- Keyboard shortcuts

## Core Interaction Methods

### Element Selection
```javascript
// By ID (fastest)
document.getElementById('elementId');

// By CSS selector
document.querySelector('.button.primary');
document.querySelectorAll('.menu-item');

// By text content
function findByText(text) {
    return Array.from(document.querySelectorAll('*')).find(el => 
        el.textContent.includes(text)
    );
}

// By XPath
function findByXPath(xpath) {
    const result = document.evaluate(xpath, document, null, XPathResult.FIRST_ORDERED_NODE_TYPE);
    return result.singleNodeValue;
}
```

### Click Operations
```javascript
// Simple click
element.click();

// Complex click (with position)
function clickAt(element, x, y) {
    const rect = element.getBoundingClientRect();
    const event = new MouseEvent('click', {
        clientX: rect.left + x,
        clientY: rect.top + y,
        bubbles: true
    });
    element.dispatchEvent(event);
}

// Right click (context menu)
element.addEventListener('contextmenu', handler);
element.dispatchEvent(new MouseEvent('contextmenu', { button: 2 }));

// Double click
element.dispatchEvent(new MouseEvent('dblclick', { bubbles: true }));
```

### Keyboard Input
```javascript
// Type text into input
function typeText(element, text) {
    element.focus();
    element.value = text;
    element.dispatchEvent(new Event('input', { bubbles: true }));
    element.dispatchEvent(new Event('change', { bubbles: true }));
}

// Simulate key press
function pressKey(key, modifiers = {}) {
    const event = new KeyboardEvent('keydown', {
        key: key,
        code: `Key${key.toUpperCase()}`,
        bubbles: true,
        ...modifiers
    });
    document.activeElement.dispatchEvent(event);
}

// Common shortcuts
function copySelection() { pressKey('c', { ctrlKey: true }); }
function paste() { pressKey('v', { ctrlKey: true }); }
function save() { pressKey('s', { ctrlKey: true }); }
function selectAll() { pressKey('a', { ctrlKey: true }); }
function undo() { pressKey('z', { ctrlKey: true }); }
function redo() { pressKey('y', { ctrlKey: true }); }
```

### Form Interactions
