## Procedural Textures

### Brick Texture
```javascript
function generateBrickTexture(width, height, brickWidth, brickHeight, mortarSize) {
    const canvas = createCanvas(width, height);
    const ctx = canvas.getContext('2d');

    const cols = Math.ceil(width / brickWidth);
    const rows = Math.ceil(height / brickHeight);

    // Background (mortar)
    ctx.fillStyle = '#888888';
    ctx.fillRect(0, 0, width, height);

    for (let row = 0; row < rows; row++) {
        const offset = (row % 2) * (brickWidth / 2);
        for (let col = 0; col < cols; col++) {
            const x = col * brickWidth + offset;
            const y = row * brickHeight;

            // Random brick color
            const hue = 20 + Math.random() * 20;
            const sat = 40 + Math.random() * 20;
            const lit = 40 + Math.random() * 20;
            ctx.fillStyle = `hsl(${hue}, ${sat}%, ${lit}%)`;

            ctx.fillRect(
                x + mortarSize,
                y + mortarSize,
                brickWidth - mortarSize * 2,
                brickHeight - mortarSize * 2
            );
        }
    }

    return canvas;
}
```

### Metal Texture
```javascript
function generateMetalTexture(width, height, type) {
    const canvas = createCanvas(width, height);
    const ctx = canvas.getContext('2d');

    // Base metallic color
    const colors = {
        steel: { r: 180, g: 180, b: 190 },
        copper: { r: 184, g: 115, b: 51 },
        gold: { r: 212, g: 175, b: 55 },
        iron: { r: 120, g: 120, b: 125 }
    };

    const base = colors[type] || colors.steel;
    const imageData = ctx.createImageData(width, height);

    for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
            const i = (y * width + x) * 4;

            // Add noise for texture
            const noise = (Math.random() - 0.5) * 30;
            const scratch = Math.random() > 0.98 ? 50 : 0;

            imageData.data[i] = Math.min(255, Math.max(0, base.r + noise + scratch));
            imageData.data[i+1] = Math.min(255, Math.max(0, base.g + noise + scratch));
            imageData.data[i+2] = Math.min(255, Math.max(0, base.b + noise + scratch));
            imageData.data[i+3] = 255;
        }
    }

    ctx.putImageData(imageData, 0, 0);
    return canvas;
}
```

